UPDATE qna_notification_log
SET status = 'SENT', sent_at = NOW()
WHERE id = #{id}

UPDATE qna_notification_log
SET status = 'FAILED', retry_count = retry_count + 1, last_error = #{error}
WHERE id = #{id}

UPDATE qna_notification_log
SET status = 'DEAD_LETTER', retry_count = retry_count + 1, last_error = #{error}
WHERE id = #{id}
